alter table public.crm_accounts add column if not exists partner_ref text, add column if not exists company_type text, add column if not exists parent_account_id uuid references public.crm_accounts(id) on delete set null, add column if not exists customer_rank integer not null default 0, add column if not exists supplier_rank integer not null default 0, add column if not exists industry_code text, add column if not exists legal_form text, add column if not exists language_code text, add column if not exists timezone text, add column if not exists sales_region text, add column if not exists sales_team text, add column if not exists account_manager text, add column if not exists payment_method text, add column if not exists tax_exemption_code text, add column if not exists tax_classification text, add column if not exists credit_status text, add column if not exists price_list text, add column if not exists fiscal_position text, add column if not exists delivery_method text, add column if not exists shipping_terms text, add column if not exists billing_cycle text, add column if not exists invoice_email text, add column if not exists remittance_email text, add column if not exists dunning_procedure text;
alter table public.crm_contacts add column if not exists salutation text, add column if not exists middle_name text, add column if not exists suffix text, add column if not exists title text, add column if not exists contact_role text, add column if not exists phone_extension text, add column if not exists preferred_channel text, add column if not exists timezone text, add column if not exists do_not_contact boolean not null default false;
alter table public.crm_opportunities add column if not exists sales_team text, add column if not exists sales_person text, add column if not exists campaign text, add column if not exists lead_source_detail text, add column if not exists next_activity_date date, add column if not exists forecast_category text;
alter table public.enterprise_profiles add column if not exists legal_form text, add column if not exists company_code text, add column if not exists sales_organization text, add column if not exists distribution_channel text, add column if not exists division text, add column if not exists purchasing_organization text, add column if not exists lei_number text, add column if not exists parent_company text, add column if not exists registered_capital numeric(20,2), add column if not exists stock_exchange text, add column if not exists fiscal_year_end text;
alter table public.trade_products add column if not exists material_type text, add column if not exists product_group text, add column if not exists product_family text, add column if not exists base_unit text, add column if not exists alternative_units jsonb not null default '[]'::jsonb, add column if not exists volume numeric(20,6), add column if not exists volume_unit text, add column if not exists country_of_origin text, add column if not exists tax_category text, add column if not exists cost_price numeric(20,6), add column if not exists serial_tracking boolean not null default false, add column if not exists batch_tracking boolean not null default false, add column if not exists shelf_life_days integer, add column if not exists product_images jsonb not null default '[]'::jsonb;
create index if not exists crm_accounts_parent_idx on public.crm_accounts(parent_account_id);
